#ifndef CGAL_DOMAIN_POLYHEDRA_H
#define CGAL_DOMAIN_POLYHEDRA_H

#define _USE_MATH_DEFINES
#define CGAL_MESH_3_OPTIMIZER_VERBOSE
//#define CGAL_MESH_3_OPTIMIZERS_DEBUG
//#define CGAL_MESH_3_SIZING_FIELD_USE_BARYCENTRIC_COORDINATES

#include <fstream>
#include <iostream>
#include <vector>
#include <string>

//CGAL 3d mesh generation head files
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Surface_mesh.h>
#include <CGAL/boost/graph/graph_traits_Surface_mesh.h>
#include <CGAL/Mesh_triangulation_3.h>
#include <CGAL/Mesh_complex_3_in_triangulation_3.h>
#include <CGAL/Mesh_criteria_3.h>
#include <CGAL/Surface_mesh_default_criteria_3.h>
#include <CGAL/Polyhedral_mesh_domain_3.h>
#include <CGAL/Polyhedral_mesh_domain_with_features_3.h>
#include <CGAL/make_mesh_3.h>
#include <map>

// IO
#include <CGAL/IO/Polyhedron_iostream.h>

// Domain
typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Polyhedral_mesh_domain_with_features_3<K> Mesh_domain;
typedef K::Point_3 Point3d;
typedef CGAL::Surface_mesh<Point3d> Surface_mesh;

// Triangulation
#ifdef CGAL_CONCURRENT_MESH_3
  typedef CGAL::Mesh_triangulation_3<
	Mesh_domain,
    CGAL::Kernel_traits<Mesh_domain>::Kernel, // Same as sequential
    CGAL::Parallel_tag                        // Tag to activate parallelism
  >::type Tr;
#else
  typedef CGAL::Mesh_triangulation_3<Mesh_domain>::type Tr;
#endif
typedef CGAL::Mesh_complex_3_in_triangulation_3<Tr,
		Mesh_domain::Corner_index,Mesh_domain::Curve_segment_index> C3t3;
// Criteria
typedef CGAL::Mesh_criteria_3<Tr> Mesh_criteria;
// To avoid verbose function and named parameters call

// User defined header files
#include "cgal_subdomain.h"

// System namespace
using namespace std;
using namespace CGAL::parameters;

class cgal_domain_polyhedra:public cgal_subdomain{
public:
	cgal_domain_polyhedra();
	~cgal_domain_polyhedra();
	// initialize domain
	void initialize();

	// Set 3d mesh generation input file and output file, with default mesh criteria
	void setInputOutputFile(std::string strFileIn,std::string strFileOut);

	// Set domain mesh criteria
	void setDomainCriteria(const double edgeSize, const double facetAngle,
			const double facetSize,	const double facetDistance,
			const double cellRadiusEdgeRatio, const double globalSize);

	// Override function make surface mesh to off
	void makeDomainSurfaceMesh();

	// Make domain polyhedron based on the triangulated surface mesh
	void makeDomainPolyhedron();

	// Optimization parameters of Lloyd
	void setOptParametersLloyd(const int maxIteration, const double timeLimit);

	// Optimization parameters of Exude
	void setOptParametersExude(const double sliverBound, const double timeLimit);

	// Optimization parameters of Perturb
	void setOptParametersPerturb(const double silverBound, const double timeLimit);

	// Make and output mesh
	void makeOutputMesh(const std::string strMeshFormat);

	// Get input domain file
	std::string getInputDomainFile();

	// Get surface mesh file
	std::string getSurfaceMeshFile();

	// Get mesh file
	std::string getMeshFile();

protected:

private:
	std::string strfile_domain_input;
	std::string strfile_mesh_surface;
	std::string strfile_mesh_output;

	//
	//Mesh criteria
	//   parameter edge_size: a scalar field (resp. a constant) providing a space varying (resp. a uniform)
	//                        upper bound for the lengths of curve segment edges. This parameter has to be
	//                        set to a positive value when 1-dimensional features protection is used.
	double criteriaEdgeSize;
	//
	//   parameter facet_angle: a lower bound for the angles (in degrees) of the surface mesh facets.
	double criteriaFacetAngle;
	//   parameter facet_size: a scalar field (resp. a constant) describing a space varying (resp. a uniform)
	//                         upper-bound or for the radii of the surface Delaunay balls.
	double criteriaFacetSize;
	//   parameter facet_distance: a scalar field (resp. a constant) describing a space varying (resp. a uniform)
	//                             upper bound for the same distance.
	double criteriaFacetDistance;
	//   parameter cell_radius_edge_ratio: an upper bound for the radius-edge ratio of the mesh tetrahedra.
	double criteriaCellRadiusEdgeRatio;
	//   parameter cell_size: a scalar field (resp. a constant) describing a space varying (resp. a uniform)
	//                        upper-bound for the circumradii of the mesh tetrahedra.
	double critieriaGlobalSize;

	//
	//Output mesh information
	//
	//Number of vertices
	int mesh_vertices_counter;

	//Number of edges
	int mesh_edges_counter;

	//Number of faces
	int mesh_faces_counter;

	//Number of surface face counter
	int mesh_surface_faces_counter;

	//Number of cells
	int mesh_cells_counter;

	//
	//Mesh optimization parameters
	//
	int maxIterationLloyd;
	double timeLimitLloyd;
	double sliverBoundExude;
	double timeLimitExude;
	double sliverBoundPerturb;
	double timeLimitPerturb;

	// Set default image parameters
	void setDefaultParameters();
};

#endif /* CGAL_DOMAIN_POLYHEDRA_H */
